    errors = 0
    for filename in files_modified:
        if filename.endswith('.py'):

            staged_cmd = "git show :%s" % filename
            staged_contents = get_output(staged_cmd)

            sort = SortImports(
                file_path=filename,
                file_contents=staged_contents.decode(),
