def get_secrets(self, from_date_added=0):
	secrets = []
	for row in self.cursor.execute('SELECT encrypted, json_id, date_added FROM secret WHERE date_added > %s ORDER BY date_added DESC' % from_date_added):
		aes_key, json_id, date_added = cryptlib.eciesDecrypt(row[0], self.privkey), row[1], row[2]
		if aes_key != None:
			secrets.append([aes_key, json_id])
		from_date_added = max(from_date_added, date_added)
	return (secrets, from_date_added)

def _cmd_to_dict(self, arg_list):
    no_param_args = [
        'autodelete',
        'autoexpand',
        'bytes',
        'compressed',
        'force',
        'nohdr',
    ]
    one_param_args = [
        'chapsecret',
        'cleanrate',
        'copyrate',
        'delim',
        'filtervalue',
        'grainsize',
        'hbawwpn',
        'host',
        'iogrp',
        'iscsiname',
        'mdiskgrp',
        'name',
        'rsize',
        'scsi',
        'size',
        'source',
        'target',
        'unit',
        'easytier',
        'warning',
        'wwpn',
    ]



    if arg_list[0] in ('svcinfo', 'svctask'):
        if arg_list[1] == 'lsnode':
            if len(arg_list) > 4:
                ret = {'cmd': 'lsnode', 'node_id': arg_list[-1]}
            else:
                ret = {'cmd': 'lsnodecanister'}
        else:
            ret = {'cmd': arg_list[1]}
        arg_list.pop(0)
    else:
        ret = {'cmd': arg_list[0]}

    skip = False
    for i in range(1, len(arg_list)):
        if skip:
            skip = False
            continue
        if arg_list[i][0] == '-':
            if arg_list[i][1:] in no_param_args:
                ret[arg_list[i][1:]] = True
            elif arg_list[i][1:] in one_param_args:
                ret[arg_list[i][1:]] = arg_list[i + 1]
                skip = True
            else:
                raise exception.InvalidInput(
                    reason=_('unrecognized argument %s') % arg_list[i])
        else:
            ret['obj'] = arg_list[i]
    return ret

