function Minimatch (pattern, options) {
  if (!(this instanceof Minimatch)) {
    return new Minimatch(pattern, options)
  }

  if (typeof pattern !== 'string') {
    throw new TypeError('glob pattern string required')
  }

  if (!options) options = {}
  pattern = pattern.trim()

  if (path.sep !== '/') {
    pattern = pattern.split(path.sep).join('/')
  }

  this.options = options
  this.set = []
  this.pattern = pattern
  this.regexp = null
  this.negate = false
  this.comment = false
  this.empty = false

  this.make()
}

function cachedPathRelative (from, to) {
  var cwd = process.cwd()
  if (cwd !== lastCwd) {
    cache = Object.create(null)
    lastCwd = cwd
  }

  if (cache[from] && cache[from][to]) return cache[from][to]

  var result = relative.call(path, from, to)

  cache[from] = cache[from] || Object.create(null)
  cache[from][to] = result

  return result

}

async function runApp() {
	let app = express();

	app.set('port', process.env.PORT ?? 8080);

	let sessionStore = new session.MemoryStore();
	let secret = Math.random().toString();
	app.use(session({store: sessionStore, resave: true, saveUninitialized: true, secret: secret, cookie: { maxAge: 10000 }, key: 'sid'}));

	let env = process.env.NODE_ENV ?? 'development';
	if (env === 'development') {
		app.use(morgan('combined'));
	}

	app.get('/', function(req, res) {
		if (!req.session.user) {
			res.redirect('/authenticate');
		} else {
			res.statusCode = 200;
			res.sendFile(path.join(__dirname, '../client/index.html'));
		}
	});

	app.use('/content', serveStatic(path.join(__dirname, '../content')));
	app.use('/', serveStatic(path.join(__dirname, '../client')));

