										else
										{
											graph.removeTagsForCells(graph.getSelectionCells(), [tag]);
										}

										mxEvent.consume(evt);
									});

									td.appendChild(cb2);
								}

								row.appendChild(td);
							}

							tbody.appendChild(row);
						})(tags[i]);
					}
				}

				table.appendChild(tbody);
				tagCloud.appendChild(table);
			}
