function escapeArgBash(arg, interpolation, quoted) {
  let result = arg.replace(/\0/gu, "");

  if (interpolation) {
    result = result
      .replace(/\\/gu, "\\\\")
      .replace(/\n/gu, " ")
      .replace(/(^|\s)(~|#)/gu, "$1\\$2")
      .replace(/(\*|\?)/gu, "\\$1")
      .replace(/([$&;|])/gu, "\\$1")
      .replace(/([()<>])/gu, "\\$1")
      .replace(/(["'`])/gu, "\\$1")
      .replace(/\{(?=([^,.]*(?:,|\.)[^]*?)\})/gu, "\\{")
      .replace(/(?<==(?:[^]*?:)?)(~)(?=[\s+\-/0:=]|$)/gu, "\\$1");
  } else if (quoted) {
    result = result.replace(/'/gu, `'\\''`);
  }

  return result;
}

update_graph(data) {
        var that = this;
        that.network_loading(true, loadingText_creating);

        this.extended_event_uuid_mapping = data.extended_event_uuid_mapping;

        dataHandler.mapping_node_to_from_edges = {};
        dataHandler.mapping_node_to_to_edges = {};
        var node_conf;
        var newNodes = [];
        var newNodeIDs = [];
        for(var node of data.items) {
            var group, label;
            if (node.event_id != scope_id) {
                if (that.extended_event_points[node.event_id] === undefined) {
                    that.extended_event_points[node.event_id] = [];
                }
                that.extended_event_points[node.event_id].push(node.id);
            }

            if ( node.node_type == 'object' ) {
                var group =  'object';
                var label = dataHandler.generate_label(node);
                var labelHtml = escapeHtml(label) + '</br><i>' + escapeHtml(node.comment) + '</i>'
                label += ' ' + escapeHtml(node.comment)
                var striped_value = that.strip_text_value(label);
                node_conf = {
                    id: node.id,
                    uuid: node.uuid,
                    Attribute: node.Attribute,
                    event_id: node.event_id,
                    label: striped_value,
                    title: labelHtml,
                    group: group,
                    mass: 5,
                    icon: {
                        color: node.color,
                        face: '"Font Awesome 5 Free"',
                        code: that.get_FA_icon(node['meta-category']),
                    }
                };
                dataHandler.mapping_value_to_nodeID.set(label, node.id);
            } else if (node.node_type == 'tag') {
                var tag_color = node.tagContent.colour;
                group =  'tag';
                label = node.label;
                node_conf = {
                    id: node.id,
                    uuid: node.uuid,
                    label: label,
                    title: escapeHtml(label),
                    group: group,
                    mass: 20,
                    color: {
                        background: tag_color,
                        border: tag_color
                    },
                    font: {
                        color: getTextColour(tag_color),
                        bold: true,
                        size: 28
                    },
                    shapeProperties: {
                        borderRadius: 6
                    }
                };
                dataHandler.mapping_value_to_nodeID.set(label, node.id);
            } else if (node.node_type == 'keyType') {
                group = 'keyType';
                label = that.scope_keyType + ": " + node.label;
                var striped_value = that.strip_text_value(label);
                node_conf = {
                    id: node.id,
                    label: striped_value,
                    title: escapeHtml(label),
                    group: group
                };
                dataHandler.mapping_value_to_nodeID.set(label, node.id);
            } else {
                group =  'attribute';
                label = escapeHtml(node.type) + ': ' + node.label;
                label += ' ' + escapeHtml(node.comment)
                var labelHtml = escapeHtml(label) + '</br><i>' + escapeHtml(node.comment) + '</i>'
                var striped_value = that.strip_text_value(label);
                node_conf = {
                    id: node.id,
                    uuid: node.uuid,
                    event_id: node.event_id,
                    label: striped_value,
                    title: labelHtml,
                    group: group,
                    mass: 5,
                };
                if (node.type == 'attachment' && isPicture(node.label)) {
                    node_conf.group = 'attribute_image';
                    node_conf.size = $('#slider_display_picture_size').val();
                    node_conf.image = baseurl + '/attributes/viewPicture/' + node.id + '/1';
                }
                dataHandler.mapping_value_to_nodeID.set(label, node.id);
            }

            newNodes.push(node_conf);
            newNodeIDs.push(node.id);
        }
        var old_node_ids = that.nodes.getIds();
        for (var old_id of old_node_ids) {
            if (old_id == "rootNode:attribute" || old_id == "rootNode:object" || old_id == "rootNode:tag" || old_id == "rootNode:keyType") {
                continue;
            }
            if (newNodeIDs.indexOf(old_id) == -1) {
                that.nodes.remove(old_id);
            }
        }

        that.nodes.update(newNodes);

        var newRelations = [];
        var newRelationIDs = [];
        for(var rel of data.relations) {
            var rel = {
                id: rel.id,
                from: rel.from,
                to: rel.to,
                label: rel.type,
                title: rel.comment,
                color: {
                    opacity: 1.0,
                }
            };
            newRelations.push(rel);
            newRelationIDs.push(rel.id);
            if (!dataHandler.mapping_node_to_from_edges[rel.from]) {
                dataHandler.mapping_node_to_from_edges[rel.from] = [];
            }
            if (!dataHandler.mapping_node_to_to_edges[rel.to]) {
                dataHandler.mapping_node_to_to_edges[rel.to] = [];
            }
            dataHandler.mapping_node_to_from_edges[rel.from].push(rel.to);
            dataHandler.mapping_node_to_to_edges[rel.to].push(rel.from);
        }
        var old_rel_ids = that.edges.getIds();
        for (var old_id of old_rel_ids) {
            if (newRelationIDs.indexOf(old_id) == -1) {
                that.edges.remove(old_id);
            }
        }

        that.edges.update(newRelations);

        that.remove_root_nodes();
        if (!that.is_filtered) {
            if (that.scope_name == 'Reference') {
                that.add_unreferenced_root_node();
                if (that.first_draw) {
                    that.link_not_referenced_nodes();
                    that.first_draw = !that.first_draw
                }
            } else if (that.scope_name == 'Tag') {
                that.add_tag_root_node();
                if (that.first_draw) {
                    that.link_not_referenced_nodes();
                    that.first_draw = !that.first_draw
                }
            } else if (that.scope_name == 'Distribution') {
            } else if (that.scope_name == 'Correlation') {
            } else {
                that.add_keyType_root_node();
                if (that.first_draw) {
                    that.link_not_referenced_nodes();
                    that.first_draw = !that.first_draw
                }
            }
        }

        eventGraph.canDrawHull = true;
        that.network_loading(false, "");
    }

function mapToRegistry (name, config, cb) {
  log.silly('mapToRegistry', 'name', name)
  var registry

  var data = npa(name)
  if (data.scope) {
    name = name.replace('/', '%2f')

    log.silly('mapToRegistry', 'scope (from package name)', data.scope)

    registry = config.get(data.scope + ':registry')
    if (!registry) {
      log.verbose('mapToRegistry', 'no registry URL found in name for scope', data.scope)
    }
  }

  var scope = config.get('scope')
  if (!registry && scope) {
    if (scope.charAt(0) !== '@') scope = '@' + scope

    log.silly('mapToRegistry', 'scope (from config)', scope)

    registry = config.get(scope + ':registry')
    if (!registry) {
      log.verbose('mapToRegistry', 'no registry URL found in config for scope', scope)
    }
  }

  if (!registry) {
    log.silly('mapToRegistry', 'using default registry')
    registry = config.get('registry')
  }

  log.silly('mapToRegistry', 'registry', registry)

  var auth = config.getCredentialsByURI(registry)

  var normalized = registry.slice(-1) !== '/' ? registry + '/' : registry
  var uri
  log.silly('mapToRegistry', 'data', data)
  if (data.type === 'remote') {
    uri = data.spec
  } else {
    uri = url.resolve(normalized, name)
  }

  log.silly('mapToRegistry', 'uri', uri)

  cb(null, uri, scopeAuth(uri, registry, auth), normalized)
}

function onCHANNEL_OPEN(self, info) {

  let localChan = -1;
  let reason;

  const accept = () => {
    const chanInfo = {
      type: info.type,
      incoming: {
        id: localChan,
        window: MAX_WINDOW,
        packetSize: PACKET_SIZE,
        state: 'open'
      },
      outgoing: {
        id: info.sender,
        window: info.window,
        packetSize: info.packetSize,
        state: 'open'
      }
    };
    const stream = new Channel(self, chanInfo);
    self._chanMgr.update(localChan, stream);

    self._protocol.channelOpenConfirm(info.sender,
                                      localChan,
                                      MAX_WINDOW,
                                      PACKET_SIZE);
    return stream;
  };
  const reject = () => {
    if (reason === undefined) {
      if (localChan === -1)
        reason = CHANNEL_OPEN_FAILURE.RESOURCE_SHORTAGE;
      else
        reason = CHANNEL_OPEN_FAILURE.CONNECT_FAILED;
    }

    self._protocol.channelOpenFail(info.sender, reason, '');
  };
  const reserveChannel = () => {
    localChan = self._chanMgr.add();

    if (localChan === -1) {
      reason = CHANNEL_OPEN_FAILURE.RESOURCE_SHORTAGE;
      if (self.config.debug) {
        self.config.debug(
          'Client: Automatic rejection of incoming channel open: '
            + 'no channels available'
        );
      }
    }

    return (localChan !== -1);
  };

  const data = info.data;
  switch (info.type) {
    case 'forwarded-tcpip': {
      const val = self._forwarding[`${data.destIP}:${data.destPort}`];
      if (val !== undefined && reserveChannel()) {
        if (data.destPort === 0)
          data.destPort = val;
        self.emit('tcp connection', data, accept, reject);
        return;
      }
      break;
    }
    case 'forwarded-streamlocal@openssh.com':
      if (self._forwardingUnix[data.socketPath] !== undefined
          && reserveChannel()) {
        self.emit('unix connection', data, accept, reject);
        return;
      }
      break;
    case 'auth-agent@openssh.com':
      if (self._agentFwdEnabled && reserveChannel()) {
        agentQuery(self.config.agent, accept, reject);
        return;
      }
      break;
    case 'x11':
      if (self._acceptX11 !== 0 && reserveChannel()) {
        self.emit('x11', data, accept, reject);
        return;
      }
      break;
    default:
      reason = CHANNEL_OPEN_FAILURE.UNKNOWN_CHANNEL_TYPE;
      if (self.config.debug) {
        self.config.debug(
          'Client: Automatic rejection of unsupported incoming channel open '
            + `type: ${info.type}`
        );
      }
  }

  if (reason === undefined) {
    reason = CHANNEL_OPEN_FAILURE.ADMINISTRATIVELY_PROHIBITED;
    if (self.config.debug) {
       self.config.debug(
        'Client: Automatic rejection of unexpected incoming channel open for: '
          + info.type
      );
    }
  }

  reject();
}

addChild(node) {
    if(node.tagname === "__proto__") node.tagname = "#__proto__";
    if(node[":@"] && Object.keys(node[":@"]).length > 0){
      this.child.push( { [node.tagname]: node.child, [":@"]: node[":@"] });
    }else{
      this.child.push( { [node.tagname]: node.child });
    }
  }

static get(applicationId: string, mount: string) {
    const cacheInfo = AppCache.get(applicationId);
    if (!cacheInfo) {
      return;
    }
    const config = new Config();
    config.applicationId = applicationId;
    Object.keys(cacheInfo).forEach(key => {
      if (key == 'databaseController') {
        const schemaCache = new SchemaCache(
          cacheInfo.cacheController,
          cacheInfo.schemaCacheTTL,
          cacheInfo.enableSingleSchemaCache
        );
        config.database = new DatabaseController(
          cacheInfo.databaseController.adapter,
          schemaCache,
          config
        );
      } else {
        config[key] = cacheInfo[key];
      }
    });
    config.mount = removeTrailingSlash(mount);
    config.generateSessionExpiresAt = config.generateSessionExpiresAt.bind(config);
    config.generateEmailVerifyTokenExpiresAt = config.generateEmailVerifyTokenExpiresAt.bind(
      config
    );
    return config;
  }

