function getCsrfToken() {
  if (csrf)
    return csrf;
  if (document.querySelector("[data-csrf]")) {
    csrf = document.querySelector("[data-csrf]").getAttribute("data-csrf");
    return csrf;
  }
  if (window.livewireScriptConfig["csrf"] ?? false) {
